TP.register({id:"lp2-gk",lp:2,grade:"K",mode:"curriculum",checks:1,nextGrade:"1st grade",build(E){const F=E.F;const GAP="apple",HAND="hand";const AP="apple",PEAR="pear",LEMON="lemon",BEE="bee",TREE="tree",CRATE="box",TRACTOR="tractor",SQUIRREL="squirrel",BIRD="bluebird",FLOWER="sunflower",HONEY="honey",COW="cow",SEED="sprout",NUT="peanut",HOTDRINK="cocoa",CLAP="hand",LADYBUG="ladybug",BUG="caterpillar",PENCIL="pencil",BREAD="bread",BERRY="strawberry",CHEESE="cheese",CARROT="carrot",EAR="ear",DROP="drop",TALK="face";const STORY="Pip the squirrel saw a big red apple at the top of the tree. He jumped and jumped, but the apple was too high. He shook the branch, but the apple did not fall. Then his friend Dot the bluebird flew up to help. Dot pecked the stem, and the apple dropped into the soft grass. Pip and Dot shared the apple for lunch.";const CIDER="Listen to how apple cider is made. First, farmers pick ripe apples from the trees. Next, they wash the apples in cold water. Then a big press squeezes the apples very hard. Sweet juice runs out of the press. That juice is called cider. People drink cider cold or warm.";const NAME_LETTERS=["c","N","h","E","y","K","u","W","j","V"];const SOUND_LETTERS=["n","c","h","l","k","w","j","v","e","u"];const INK="#6B4A3C";const FACE=window.TP_ICON_FACE||(()=>"");const faceAt=(x,y,k,sp,mw)=>`<g transform="translate(${x},${y}) scale(${k})">${FACE(0,0,sp,mw)}</g>`;const DISP="font-family:var(--font-display);font-weight:800";const PX=v=>{if(typeof v==="number")return v;const n=parseFloat(v);return/rem|em/.test(v)?Math.round(n*16):n||80};const PICHTML=F.icon||F.pic2;const ICO=(e,sz)=>PICHTML(e,PX(sz))||e;const ico=(n,px)=>PICHTML(n,px)||n;const emXY=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;function wordGrid(ws){return`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:6px 0 10px">${ws.map(w=>`<div style="border:3px solid var(--line);border-radius:16px;text-align:center;padding:14px 6px;${DISP};font-size:clamp(2rem,6vw,3.4rem)">${w}</div>`).join("")}</div>`}function grp(e,n,per,sz){const rows=[],one=ICO(e,sz||"2.8rem");for(let i=0;i<n;i+=per)rows.push(Array(Math.min(per,n-i)).fill(one).join(""));return`<span style="display:inline-block;border:3px solid var(--line);border-radius:18px;padding:10px 14px;background:var(--surface);font-size:${sz||"2.8rem"};line-height:1.3;letter-spacing:.1em;text-align:left;vertical-align:middle;font-weight:400" role="img" aria-label="a group of pictures">${rows.join("<br>")}</span>`}function scatter(e,n,seed){const pts=[];let x=seed,tries=0,gap=62;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[40+rnd()*260,48+rnd()*170];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>4e3){tries=0;gap-=4}}return`<svg viewBox="0 0 340 260" width="340" role="img" aria-label="a scattered group of pictures"><rect x="4" y="4" width="332" height="252" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>${pts.map(p=>emXY(p[0].toFixed(0),p[1].toFixed(0),e,42)).join("")}</svg>`}function mixRows(rows,map){return`<div style="text-align:center;font-size:clamp(2.4rem,5.4vw,3.6rem);line-height:1.35;letter-spacing:.14em;margin-bottom:14px" role="img" aria-label="a mix of fruit">${rows.map(r=>[...r].map(k=>ICO(map[k],52)).join("")).join("<br>")}</div>`}const DECKS=[];function picDeck(cards,notes){let i=0;const d={reset(){i=0},render(){return`<div style="text-align:center"><p style="margin:0">Card ${i+1} of ${cards.length}</p><div style="margin:14px 0 18px;display:flex;justify-content:center;align-items:center;gap:26px;flex-wrap:wrap">${cards[i]}</div><div class="row center"><button class="btn ghost" data-d="-1" ${i===0?"disabled":""}>Back</button><button class="btn ghost" data-d="1" ${i===cards.length-1?"disabled":""}>Next</button></div></div>`},bind(root,ctx){root.querySelectorAll("[data-d]").forEach(b=>b.onclick=()=>{i=Math.max(0,Math.min(cards.length-1,i+Number(b.dataset.d)));ctx.redraw()})},print(){return`<p><em>Picture cards shown one at a time:</em> ${notes.join(" ")}</p>`}};DECKS.push(d);return d}function ladder(){const rails=`M35 8 V292 M115 8 V292`;let rungs="";for(let k=0;k<8;k++)rungs+=`M35 ${30+k*34} H115 `;const ln=(d,c,w)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;return`<svg viewBox="0 0 150 300" width="140" role="img" aria-label="A ladder"><rect x="35" y="132" width="80" height="34" fill="#E0B07A"/>`+ln(rails,INK,13)+ln(rungs,INK,12)+ln(rails,"#E0B07A",7)+ln(rungs,"#E0B07A",6)+faceAt(75,144.4,1.05,13,4.5)+"</svg>"}function signFig(){const end=e=>`<span style="font-size:3.6rem;line-height:1" aria-hidden="true">${ICO(e,"3.6rem")}</span>`;const card=(tag,t)=>`<div style="text-align:center"><div style="font-size:2.6rem;line-height:1.1" aria-hidden="true">${ICO(tag,"2.6rem")}</div><div style="border:4px solid var(--ink);border-radius:16px;background:var(--surface);min-width:150px;padding:4px 18px;${DISP};font-size:3.6rem;line-height:1.3">${t}</div></div>`;return`<div style="display:flex;align-items:center;justify-content:center;gap:18px;margin:6px 0 22px">${end(BEE)}<span style="border:6px solid var(--gold-ink);background:var(--surface);border-radius:14px;padding:8px 28px;${DISP};font-size:clamp(2.2rem,5.6vw,3.6rem)">We pick red apples.</span>${end(CRATE)}</div>
  <div class="figure" style="gap:34px">${card(AP,"t")}${card(TREE,"jam")}${card(TRACTOR,"6")}</div>`}function matchFig(){const rows=[[HONEY,["t","h","m"]],[COW,["c","s","p"]],[SEED,["n","l","s"]],[NUT,["u","n","w"]]];return`<div style="display:grid;grid-template-columns:repeat(2,auto);gap:16px 22px;justify-content:center;margin:6px 0">${rows.map((r,i)=>`<div style="display:flex;align-items:center;gap:12px;border:3px solid var(--line);border-radius:18px;padding:8px 14px;background:var(--surface)"><span class="pill" style="font-size:1.2rem">${i+1}</span><span style="font-size:3.4rem;line-height:1" aria-hidden="true">${ICO(r[0],"3.4rem")}</span>${r[1].map(l=>`<span style="border:3px solid var(--ink);border-radius:12px;min-width:1.5em;text-align:center;${DISP};font-size:2.8rem;line-height:1.35">${l}</span>`).join("")}</div>`).join("")}</div>`}function standFig(){const st=`stroke="${INK}" stroke-width="4.5" stroke-linejoin="round" stroke-linecap="round"`;return`<svg viewBox="0 0 520 404" width="470" role="img" aria-label="A farm stand with a roof, a door, and a window. A bee, an apple, and a crate are in the picture.">
  <path d="M20 392 H500" fill="none" stroke="${INK}" stroke-width="4" stroke-linecap="round"/>
  <rect x="140" y="170" width="220" height="220" rx="16" fill="#DCEEF7" ${st}/>
  <polygon points="112,170 250,66 388,170" fill="#F4A39B" ${st}/>
  ${faceAt(250,132,1.5,19,5)}
  <rect x="164" y="262" width="74" height="128" rx="10" fill="#E0B07A" ${st}/>
  ${faceAt(201,300,1.05,11,4.5)}
  <circle cx="300" cy="236" r="38" fill="#FBF6EF" ${st}/>
  ${faceAt(300,232,.9,10,4)}
  ${emXY(250,34,BEE,46)}
  ${emXY(300,350,AP,46)}
  ${emXY(446,352,CRATE,72)}</svg>`}function fruitRows(rows){return`<div style="display:inline-block;text-align:left;border:3px solid var(--line);border-radius:18px;padding:10px 18px;margin-bottom:14px;background:var(--surface);font-size:2.6rem;line-height:1.4;letter-spacing:.12em" role="img" aria-label="Rows of fruit">${rows.map(r=>Array(r[1]).fill(ICO(r[0],"2.6rem")).join("")).join("<br>")}</div>`}const VS=`<span style="${DISP};font-size:1.6rem;color:var(--muted)" aria-hidden="true">and</span>`;const cmp=picDeck([grp(AP,3,3)+VS+grp(PEAR,5,5),grp(BEE,6,3)+VS+grp(FLOWER,4,2),grp("apple:2",5,5)+VS+grp(LEMON,5,5),grp(CRATE,7,4)+VS+grp("apple:4",8,4),grp(PEAR,9,5)+VS+grp("apple:5",10,5)],["1) 3 apples and 5 pears.","2) 6 bees and 4 sunflowers.","3) 5 apples and 5 lemons.","4) 7 crates and 8 apples.","5) 9 pears and 10 apples."]);const WRITE_DIR="Draw and write on your paper. Hold it up when you finish.";const BEES="Bees help an apple orchard. In the spring, a bee flies from flower to flower. Yellow dust called pollen sticks to its legs, and the bee carries that pollen to the next flower. The pollen is what the flower needs before it can turn into an apple. The farmer keeps the bees in a wooden box called a hive. Inside the hive, the bees make honey. That is why a farmer is glad when bees live near the trees.";function polesFig(){const w=520,h=170;const bar=(y,len,lab)=>`<rect x="70" y="${y}" width="${len}" height="22" rx="11" fill="#E0B07A" stroke="${INK}" stroke-width="4"/><text x="38" y="${y+12}" font-size="28" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${lab}</text>`;return`<svg viewBox="0 0 ${w} ${h}" width="${w}" role="img" aria-label="Two picking poles that start at the same line. Pole A is longer than pole B."><rect x="4" y="4" width="${w-8}" height="${h-8}" rx="20" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/><path d="M62 30 V140" stroke="var(--line)" stroke-width="3"/>${bar(46,400,"A")}${bar(110,230,"B")}</svg>`}function flatSolidFig(){const cell=180,gap=16,w=4*(cell+gap)-gap+8,h=cell+52,st=`stroke="${INK}" stroke-width="4.5" stroke-linejoin="round"`;const cx=i=>4+i*(cell+gap)+cell/2;const box=(i,body)=>`<rect x="${4+i*(cell+gap)}" y="4" width="${cell}" height="${cell}" rx="20" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>${body}<text x="${cx(i)}" y="${cell+38}" font-size="30" font-weight="800" text-anchor="middle" fill="var(--muted)">${i+1}</text>`;const X0=cx(2)-52,Y0=56,CX=cx(3);let b=box(0,`<circle cx="${cx(0)}" cy="94" r="58" fill="#F4A39B" ${st}/>`);b+=box(1,`<rect x="${cx(1)-56}" y="38" width="112" height="112" rx="8" fill="#DCEEF7" ${st}/>`);b+=box(2,`<polygon points="${X0},${Y0+30} ${X0+30},${Y0} ${X0+134},${Y0} ${X0+104},${Y0+30}" fill="#F6E7CF" ${st}/><rect x="${X0}" y="${Y0+30}" width="104" height="92" fill="#E8BE86" ${st}/><polygon points="${X0+104},${Y0+30} ${X0+134},${Y0} ${X0+134},${Y0+92} ${X0+104},${Y0+122}" fill="#D9A26A" ${st}/>`);b+=box(3,`<rect x="${CX-44}" y="48" width="88" height="88" fill="#C7E3C9" ${st}/><ellipse cx="${CX}" cy="136" rx="44" ry="18" fill="#C7E3C9" ${st}/><ellipse cx="${CX}" cy="48" rx="44" ry="18" fill="#E4F3E5" ${st}/>`);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,900)}" role="img" aria-label="Four shape cards: a flat circle, a flat square, a cube, and a can shape">${b}</svg>`}const crateBox=t=>`<div style="border:4px dashed var(--line);border-radius:18px;min-width:180px;height:92px;display:flex;align-items:flex-end;justify-content:center;background:var(--surface)"><span style="font-size:1.05rem;color:var(--muted);padding-bottom:6px">${t}</span></div>`;function sevenFig(){return`<div style="text-align:center">${grp("apple:6",7,7,"2.6rem")}</div><div class="figure" style="gap:28px;margin-top:12px">${crateBox("Crate 1")}${crateBox("Crate 2")}</div>`}function addFig(){return`<div class="figure" style="align-items:center;gap:14px">${grp("apple:8",5,5,"2.6rem")}<span class="big">and</span>${grp("apple:8",3,3,"2.6rem")}</div><div class="figure" style="margin-top:12px">${grp(BEE,9,9,"2.2rem")}</div>`}function teenFig(){return`<div class="figure" style="align-items:center;gap:16px">${grp("apple:2",10,5,"2.4rem")}<span class="big">and</span>${grp("apple:2",4,4,"2.4rem")}</div><p class="big" style="text-align:center">One full crate holds 10 apples.</p>`}function weighFig(){return`<div class="figure" style="align-items:flex-end;gap:30px"><div style="text-align:center">${grp("apple:4",3,3,"2.4rem")}<p style="margin:6px 0 0;font-size:1.1rem;color:var(--muted)">Basket A</p></div><div style="text-align:center">${grp("apple:4",8,4,"2.4rem")}<p style="margin:6px 0 0;font-size:1.1rem;color:var(--muted)">Basket B</p></div></div>`}function bookFig(){const line=(t,e)=>`<div style="display:flex;align-items:center;justify-content:center;gap:18px;margin:12px 0"><span style="${DISP};font-size:clamp(1.7rem,4.4vw,2.6rem)">${t}</span><span style="line-height:1" aria-hidden="true">${ICO(e,"2.8rem")}</span></div>`;return`<div style="border:5px solid var(--gold-ink);border-radius:22px;background:var(--surface);padding:14px 22px 18px;max-width:640px;margin:0 auto"><p style="text-align:center;${DISP};font-size:1.3rem;margin:0;color:var(--muted)">I See an Apple</p>`+line("I see an apple.",AP)+line("It is red.",AP)+line("I see a pear.",PEAR)+line("It is not red.",PEAR)+line("The apple is big.",AP)+line("The pear is little.",PEAR)+line("I can get an apple.",HAND)+line("I like it.",AP)+`</div>`}const STOPS=[{id:1,title:"Farm Stand Sign",short:"Sign",parts:[{title:"Letter Apples",std:["RF.K.1"],kind:"words",full:E.alphabet(),words:NAME_LETTERS,unit:"Letter",n:10,dur:75,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters",key:["The student says the name of each letter: c, N, h, E, y, K, u, W, j, V. Count a letter correct when the name is right. Sounds are not needed here.","Write down any letters that were missed or mixed up, such as u and n, or h and n."]},{title:"Look at the Sign",std:["RF.K.1"],n:4,dur:60,dir:"Look at the sign and the cards. Answer out loud.",desc:"print concepts (counting words, telling a letter from a word)",html:()=>signFig(),key:["Ask: How many words are on the sign? (4. You may slide your pointer under the sign, but do not count for the student.)","Ask: Look at the three cards. Which card has just one letter on it? (the apple card. The tractor card has 6 on it, which is a number and not a letter. If the student points at the tractor card, mark this one wrong and note that the student still needs the difference between letters and numbers.)","Ask: Which card has a word on it? (the tree card)","Ask: How many letters are in the word on the tree card? (3)"]}]},{id:2,title:"Ladder Climb",short:"Ladder",parts:[{title:"Climb and Count",std:["K.CC.A.1"],n:3,label:"checks met",dur:90,dir:"Count out loud. Start at 1. Go as high as you can.",desc:"counting out loud by ones",key:["Say: Climb the ladder with your voice. Start at 1 and count as high as you can. Check: counts 1 to 10 in order with no skips.","Counts 11 to 20 in order. Listen for skipped teen numbers such as 13, 15, and 16.","Keeps counting past 20 and crosses into a new ten, such as 29 to 30. Stop at 100. Write the highest number said before a mistake. The end of year goal is 100."]},{title:"Crates of Ten",std:["K.CC.A.1"],n:2,label:"checks met",dur:45,dir:"Count by tens out loud.",desc:"counting by tens",html:()=>`<p class="big" style="text-align:center">10 apples in every crate</p>`,picSup:true,fig:()=>'<div style="display:flex;flex-wrap:wrap;justify-content:center;gap:8px 12px;max-width:560px;margin:8px auto" role="img" aria-label="10 crates of apples, each crate labeled 10">'+Array(10).fill('<img alt="" src="data:image/webp;base64,'+window.TP_IMG1.crate10+'" style="width:100px;height:auto">').join("")+'</div>',key:["Say: Every crate holds 10 apples. Count by tens, one crate at a time. Check: says 10, 20, 30, 40, 50 for the top row.","Keeps going for the bottom row: 60, 70, 80, 90, 100. Write the last number said in order."]}]},{id:3,title:"Busy Bee Sounds",short:"Bee Sounds",parts:[{title:"Rhyme Hive",std:["RF.K.2"],n:5,dur:75,dir:"Listen to your teacher. Answer out loud.",desc:"hearing and making rhymes",html:()=>'<div style="text-align:center;margin:8px 0"><img alt="Rhyming Words picture card: bee and tree, apple and crate, weed and log for seed, stem and stick for pick, and a pie" src="data:image/webp;base64,'+window.TP_IMG1.rhymecard+'" style="width:720px;max-width:100%;height:auto;border-radius:16px"></div>',key:["Ask: Do bee and tree rhyme? (yes)","Ask: Do apple and crate rhyme? (no)","Ask: Which word rhymes with seed: weed or log? (weed)","Ask: Which word rhymes with pick: stem or stick? (stick)","Say: Tell me a word that rhymes with pie. (my, tie, sky, or any rhyme. Silly words count.)"]},{title:"Clap and Listen",std:["RF.K.2"],n:6,dur:75,dir:"Clap the parts you hear. Then listen for sounds.",desc:"clapping syllables, blending word parts, and saying first sounds",html:()=>'<div style="text-align:center;margin:8px 0"><img alt="Six pictures: apple, tree, ladybug, beehive, bee, and barn" src="data:image/webp;base64,'+window.TP_IMG1.clapset+'" style="width:600px;max-width:100%;height:auto"></div>',key:["Say: Clap the parts in apple. (2 claps: ap-ple)","Say: Clap the parts in tree. (1 clap)","Say: Clap the parts in ladybug. (3 claps: la-dy-bug)","Say: I will say a word in two parts. Put them together: /h/ ... ive. (hive)","Ask: What is the first sound in bee? (/b/. The sound, not the letter name.)","Ask: What is the first sound in farm? (/f/)"]}]},{id:4,title:"Apple Count",short:"Count",parts:[{title:"How Many",std:["K.CC.B.4"],dur:75,dir:"Count out loud. Your teacher will point for you.",desc:"counting objects and telling how many",fig:()=>`<div class="figure" style="align-items:center">${grp("apple:9",7,7,"3rem")}${scatter(BEE,9,11)}</div>`,qs:["Count the apples in the row. How many?","One more apple rolls in. How many apples now?","Count the bees. How many?","If we count the bees again in a new order, how many will there be?"],key:["7. Says one number for each apple as you point.","8, without counting them all again","9. Says one number for each bee. Point to the bees the way the student tells you so none is counted twice.","9. The number stays the same in any order. The student may count again to check."]},{title:"Count On",std:["K.CC.B.4"],dur:75,dir:"Start at the number your teacher says. Count out loud.",desc:"counting forward from a given number",fig:()=>`<div class="figure">${F.pic(BUG,"","4.5rem")}</div>`,qs:["Start at 3. Count to 8.","Start at 5. Count to 10.","Start at 9. Count to 14.","Start at 12. Count to 20."],key:["3, 4, 5, 6, 7, 8. Starts at 3 and does not go back to 1.","5, 6, 7, 8, 9, 10","9, 10, 11, 12, 13, 14","12, 13, 14, 15, 16, 17, 18, 19, 20"]}]},{id:5,title:"Squirrel Story",short:"Story",parts:[{std:["RL.K.1"],n:5,dur:90,dir:"Listen to the story. Then answer your teacher’s questions.",desc:"asking and answering questions about key details in a story read aloud",picSup:true,fig:()=>'<div style="text-align:center;margin:8px 0"><img alt="Six story pictures in order: a squirrel looks up at an apple, jumps for it, shakes the branch, a bluebird flies over, the apple falls, and the squirrel and bluebird share the apple" src="data:image/webp;base64,'+window.TP_IMG1.squirrel+'" style="width:720px;max-width:100%;height:auto;border-radius:16px"></div>',read:STORY,key:["Ask: Who wanted the apple? (Pip the squirrel)","Ask: Where was the apple? (at the top of the tree, up high)","Ask: What did Pip do to try to get the apple? (jumped, or shook the branch)","Ask: Who helped Pip? How? (Dot the bluebird pecked the stem so the apple fell.)","Say: Now you ask me a question about the story. (asks a question about the story. If needed, offer a starter word: who, what, or where.)"]}]},{id:6,title:"Fill the Crates",short:"Crates",parts:[{std:["K.CC.C.6"],n:5,dur:75,dir:"Look at the two groups. Answer out loud.",desc:"comparing two groups of objects (more, fewer, the same)",render:()=>cmp.render(),bind:(root,ctx)=>cmp.bind(root,ctx),printHtml:()=>cmp.print(),key:["Card 1. Ask: Are there more apples or more pears? (pears. 5 is more than 3.)","Card 2. Ask: Which group has fewer, the bees or the flowers? (the flowers. 4 is fewer than 6.)","Card 3. Ask: Are there more apples or more lemons? (the same, 5 and 5. If the student picks one, ask: How do you know? Count to check.)","Card 4. Ask: Is there an apple for every crate? Which has more? (yes, and one apple is left over. Apples have more, 8 and 7.)","Card 5. Ask: Which group has fewer, the pears or the apples? (the pears. 9 is fewer than 10.)"]}]},{id:7,title:"Letter Tree",parts:[{title:"Sound Apples",std:["RF.K.3"],kind:"words",words:SOUND_LETTERS,unit:"Letter",n:10,dur:75,dir:"Say the sound each letter makes.",desc:"saying the sounds of letters",key:["The student says the most common sound for each letter: n /n/, c /k/, h /h/, l /l/, k /k/, w /w/, j /j/, v /v/, e as in egg, u as in up. The letter name is not needed here.","Long vowel sounds for e and u are also fine. Write down any sounds that were missed."]},{title:"First Sound Match",std:["RF.K.3"],n:4,dur:60,dir:"Listen to the word. Tell which letter makes the first sound.",desc:"matching first sounds to letters",html:()=>matchFig(),key:["Say: Number 1 is honey. Which letter makes the first sound in honey? (h, the middle letter)","Say: Number 2 is cow. Which letter makes the first sound in cow? (c, the first letter)","Say: Number 3 is seed. Which letter makes the first sound in seed? (s, the last letter)","Say: Number 4 is nut. Which letter makes the first sound in nut? (n, the middle letter)"]}]},{id:8,title:"Fruit Sort",short:"Sort",parts:[{std:["K.MD.B.3"],dur:90,dir:"Look at the fruit. Count out loud.",desc:"sorting objects into groups, counting each group, and ordering the groups by count",fig:()=>mixRows(["aplapap","plapalp"],{a:AP,p:PEAR,l:LEMON}),qs:["How many apples?","How many pears?","How many lemons?","Which fruit has the most?","Which fruit has the fewest?","Say the fruits in order from fewest to most."],key:["5 apples","6 pears","3 lemons","Pears (6)","Lemons (3)","Lemons, apples, pears (3, 5, 6)"]}]},{id:9,title:"Cider Time",short:"Cider",parts:[{std:["SL.K.2"],n:5,dur:90,dir:"Listen to your teacher. Then answer out loud.",desc:"answering questions and asking for help after listening to spoken information",picSup:true,fig:()=>'<div style="text-align:center;margin:8px 0"><img alt="Five pictures in order: children pick apples, the apples are washed in a tub, a press squeezes the apples and cider pours into a jug, the jug of cider sits next to a warm mug, and the children drink cider" src="data:image/webp;base64,'+window.TP_IMG1.cidersteps+'" style="width:720px;max-width:100%;height:auto;border-radius:16px"></div>',read:CIDER,key:["Ask: What do the farmers do first? (pick the apples)","Ask: What happens to the apples after they are picked? (they are washed in cold water)","Ask: What squeezes the apples? (a big press)","Ask: What is the juice called? (cider)","Say: I used the word press. When you do not know a word, what can you ask me? (asks for help, such as: What is a press? or Can you say it again?)"]}]},{id:10,title:"Draw and Write",short:"Write",parts:[{alt:{group:"write",key:"apples",label:"All About Apples",icon:"🍎",hint:"Tell what you know about apples"},std:["W.K.2"],n:3,label:"checks met",dur:180,dir:WRITE_DIR,desc:"an informative draw-and-write piece about apples",html:()=>`<div class="figure">${F.pic("apple:2","","6rem")}</div><p class="big">Draw an apple. Write a letter or a word to name it. Then write or tell one thing you know about apples.</p>`,key:["Names what the piece is about: an apple. The student may say it, label the picture, or write a letter or word for it.","Gives at least one piece of true information about apples, such as: Apples grow on trees. Apples can be red.","Uses drawing, telling, or writing (any mix) to share the information"]},{alt:{group:"write",key:"trees",label:"All About Trees",icon:"🌳",hint:"Tell what you know about trees"},std:["W.K.2"],n:3,label:"checks met",dur:180,dir:WRITE_DIR,desc:"an informative draw-and-write piece about trees",html:()=>`<div class="figure">${F.pic(TREE,"","6rem")}</div><p class="big">Draw a tree. Write a letter or a word to name it. Then write or tell one thing you know about trees.</p>`,key:["Names what the piece is about: a tree. The student may say it, label the picture, or write a letter or word for it.","Gives at least one piece of true information about trees, such as: Trees have leaves. Birds live in trees.","Uses drawing, telling, or writing (any mix) to share the information"]}]},{id:11,title:"Farm Stand Shapes",short:"Shapes",parts:[{std:["K.G.A.1"],dur:90,dir:"Look at the farm stand. Answer out loud.",desc:"naming shapes in a picture and telling where things are (above, beside, below)",fig:()=>'<div style="text-align:center;margin:8px 0"><img alt="A farm stand with a red triangle roof, a green rectangle door, and a round window. A bee sits above the roof. A barrel of sunflowers and a crate of apples are beside the stand, and an apple is below the window." src="data:image/webp;base64,'+window.TP_IMG1.farmstand+'" style="width:600px;max-width:100%;height:auto;border-radius:16px"></div>',qs:["What shape is the roof?","What shape is the door?","What shape is the window?","What is above the roof?","What is beside the farm stand?","Where is the apple?"],key:["Triangle","Rectangle","Circle","The bee","The crate. Also accept the barrel of sunflowers.","Below the window, or under the window. Also accept beside the door or in front of the farm stand."]}]},{id:12,title:"Bee Talk",parts:[{title:"Say It Right",std:["L.K.1"],n:5,dur:75,dir:"Listen to your teacher. Say your answer out loud.",desc:"spoken grammar items (plural nouns, question words, complete sentences)",picSup:true,fig:()=>'<div style="text-align:center;margin:8px 0"><img alt="Picture cards: one apple and two apples, one peach and two peaches, a girl thinking of a question, a tree, and a bee flying to a flower" src="data:image/webp;base64,'+window.TP_IMG1.saybee+'" style="width:600px;max-width:100%;height:auto;border-radius:16px"></div>',key:["Say: One apple, two ____. (apples)","Say: One peach, two ____. (peaches)","Say: Ask me a question that starts with Who. (asks a who question)","Say: Tell me a whole sentence about a tree. (a complete sentence, such as: The tree is tall.)","Say: My sentence is: The bee flies. Make it longer. Tell where the bee flies. (adds a where phrase, such as: The bee flies to the flower.)"]},{title:"Write Letters",std:["L.K.1"],n:4,dur:75,dir:"Write each letter your teacher says. Hold up your paper.",desc:"printing uppercase and lowercase letters",key:["Say: Write the first letter of your name. (a letter you can recognize)","Say: Write an uppercase H. (H)","Say: Write a lowercase t. (t)","Say: Write a lowercase c. (c. For all four letters, count it correct when you can tell what the letter is. Backward letters are common at this age. Write down which ones.)"]}]},{id:13,title:"Picnic Chat",short:"Picnic",parts:[{std:["SL.K.4"],n:3,label:"checks met",dur:60,dir:"Tell your teacher out loud. Use lots of details.",desc:"describing a familiar food with details",html:()=>`<div class="figure">${F.pic(BREAD)}${F.pic(BERRY)}${F.pic(CHEESE)}${F.pic(CARROT)}</div><p class="big" style="text-align:center">Tell me about a food you like to eat.</p>`,key:["Names a food and tells something about it","Adds a detail when you ask: What does it look like? How does it taste?","Adds another detail when you ask: When do you eat it? Who eats it with you?"]}]},{id:14,title:"Orchard Bees",short:"Bees",parts:[{title:"What the Facts Say",std:["RI.K.1"],n:4,dur:50,read:BEES,dir:"Listen to the facts about bees. Then answer out loud.",desc:"asking and answering questions about key details in an informational text read aloud",picSup:true,fig:()=>'<div style="text-align:center;margin:8px 0"><img alt="How an apple grows with help from bees: a bee with pollen on a blossom, the bee drinking from the blossom, a small green apple, and a ripe red apple. A bee flies near a hive, honey sits on a table, and a farmer gives a thumbs up." src="data:image/webp;base64,'+window.TP_IMG1.beefacts+'" style="width:600px;max-width:100%;height:auto;border-radius:16px"></div>',key:["Read the facts out loud once. Read them again if the student asks.","Ask: What sticks to a bee's legs? (pollen, the yellow dust)","Ask: Where does the farmer keep the bees? (in a hive, a wooden box)","Ask: Why is the farmer glad that bees live near the trees? (the bees carry pollen, and a flower needs pollen before it can turn into an apple)","Say: Now you ask me a question about the bees. (asks a question about the facts, not about something else. If needed, offer a starter word: what, where, or why.)"]},{title:"Answer the Question",std:["W.K.8"],n:3,label:"checks met",dur:45,dir:"Answer your teacher out loud. You may draw on your paper too.",desc:"answering a question using information from a text just heard and from the student's own experience",html:()=>`<div class="figure">${F.pic(BEE,"","5rem")}${F.pic(PENCIL,"","5rem")}</div><p class="big" style="text-align:center">How do bees help the apple trees?</p>`,key:["Say: Here is our question. How do bees help the apple trees? Use the facts we just heard.","Look for: pulls at least one fact from the reading, such as bees carry pollen, or bees go flower to flower.","Say: Now think about yourself. Have you ever seen a bee or a bug outside? Tell me one thing you remember. Look for: one real detail from the student's own life.","Look for: the answer actually answers the question that was asked, instead of telling something else about bees. The student may draw the answer and tell you about the drawing."]}]},{id:15,title:"Little Apple Book",short:"Book",parts:[{std:["RF.K.4"],n:31,label:"words read correctly",dur:60,dir:"Read the little book out loud. Point to each word as you read.",desc:"reading an eight-line emergent-reader text out loud and telling what it is about",html:()=>'<div style="text-align:center;margin:8px 0"><img alt="Little book page: I see an apple. It is red. I see a pear. It is not red. The apple is big. The pear is little. I can get an apple. I like it. A farm stand with an apple, a pear, and a basket of apples is beside the words." src="data:image/webp;base64,'+window.TP_IMG1.littlebook+'" style="width:680px;max-width:100%;height:auto;border-radius:18px"></div>',key:["Count the words the student reads correctly, out of 31, and enter the number in the box. A word the student fixes without help counts. Write down the words that were missed.","Say: This is a little book about an apple and a pear. Read it out loud and point to each word.","Lines 1 to 4: I see an apple. It is red. I see a pear. It is not red. Count it correct when the student reads the words and the finger lands on one word at a time, left to right.","Lines 5 to 8: The apple is big. The pear is little. I can get an apple. I like it. Picture words, carried by the picture beside them: apple, pear. The rest are sight words or sound-out words (get)","Ask: What is this little book about? (an apple and a pear, or getting an apple at the farm stand. Any answer that shows the student knows what was read.)","The pictures are there to help. Using the picture to get apple or pear is fine at this grade. Note if the student read from the picture alone without looking at the words."]}]},{id:16,title:"Tell About It",short:"Tell",parts:[{title:"Which Do You Like?",std:["W.K.1"],n:3,label:"checks met",dur:60,dir:WRITE_DIR,desc:"an opinion draw-and-write piece with a topic and a reason",html:()=>`<div style="display:flex;flex-wrap:wrap;justify-content:center;gap:14px;margin:8px 0"><img alt="Four children pick red apples from a tree and hold a basket of apples" src="data:image/webp;base64,${window.TP_IMG1.pick2}" style="width:340px;max-width:100%;height:auto;border-radius:16px"><img alt="Five children smile and drink warm apple cider from mugs with apples on them" src="data:image/webp;base64,${window.TP_IMG1.cider2}" style="width:340px;max-width:100%;height:auto;border-radius:16px"></div><p class="big">Which do you like better, picking apples or drinking cider? Draw it. Then tell or write which one you like and why.</p>`,key:["Names the topic: tells you the two things the piece is about, picking apples or cider.","States an opinion: says or writes which one, such as I like cider. Drawing plus telling counts.","Gives a reason when you ask why, such as: It is warm, or I like to climb the ladder.","Dictating to an adult is allowed for this standard. Note whether the student wrote any letters."]},{title:"What Happened",std:["W.K.3"],n:3,label:"checks met",dur:60,dir:WRITE_DIR,desc:"a narrative draw-and-write piece with two events in order and a reaction",html:()=>`<div class="figure">${F.pic(TREE,"","5rem")}${F.pic(PENCIL,"","5rem")}</div><p class="big">Draw one thing that happened to you outside. Then tell what happened first and what happened next, and how you felt.</p>`,key:["Tells about one real thing that happened. Any event counts, at an orchard or anywhere outside.","Tells two things in the order they happened. Listen for order words such as first, then, next, or after that.","Gives a reaction: how the student felt about it, such as It was fun, or I was tired.","Dictating to an adult is allowed. Note whether the student wrote any letters or words."]}]},{id:17,title:"Crate Math",short:"Crate Math",parts:[{title:"Apples In, Apples Out",std:["K.OA.A.2"],n:3,dur:45,dir:"Look at the pictures. Answer out loud. You may draw to help.",desc:"adding and subtracting within 10 in word problems",fig:()=>addFig(),key:["Point to the two groups of apples. Say: Pip put 5 apples in the basket. Then he put in 3 more. How many apples are in the basket now? (8)","Say: 8 apples were in the basket. Pip took 2 out for lunch. How many apples are left? (6)","Point to the bees. Say: 9 bees were on the flowers. 4 of them flew back to the hive. How many bees are left on the flowers? (5)","Counting the pictures, drawing, or using fingers all count at this grade. Note which one the student used."]},{title:"Two Crates",std:["K.OA.A.3"],n:3,dur:45,dir:"Look at the 7 apples and the two crates. Answer out loud.",desc:"breaking 7 into two parts in more than one way",fig:()=>sevenFig(),key:["Say: Here are 7 apples and two crates. Put some in crate 1 and the rest in crate 2. Tell me how many go in each. (any pair that makes 7: 1 and 6, 2 and 5, 3 and 4, 4 and 3, 5 and 2, 6 and 1, and 0 and 7 counts too)","Say: Now do it a different way. Tell me another pair that uses all 7 apples. (a second pair that makes 7, different from the first one)","Say: Say it like a number sentence. 7 is ____ and ____. (says both parts, such as 7 is 3 and 4)","Count this correct when both pairs really add to 7. If the student gives the same pair twice, say: Tell me one that is not the same as before."]},{title:"Ten and Some More",std:["K.NBT.A.1"],n:3,dur:45,dir:"Look at the full crate and the loose apples. Answer out loud.",desc:"seeing a teen number as ten ones and some more ones",fig:()=>teenFig(),key:["Say: This crate is full. How many apples are in a full crate? (10)","Say: Count the loose apples beside it. How many? (4)","Say: How many apples in all? (14. Counting on from 10 is the goal: 11, 12, 13, 14. Counting all 14 from 1 counts as correct too, so note which one the student did.)","Say: Finish this: 14 is ten and ____ more. (4)"]}]},{id:18,title:"Poles and Shapes",short:"Compare",parts:[{title:"Longer and Heavier",std:["K.MD.A.2"],n:3,dur:45,dir:"Look at the poles and the baskets. Answer out loud.",desc:"comparing two objects directly by length and by weight, and describing the difference",fig:()=>`<div class="figure" style="flex-direction:column;align-items:center;gap:14px">${polesFig()}${weighFig()}</div>`,key:["Point to the two picking poles. Say: Both poles start at the same line. Which pole is longer? (A)","Say: Now tell me about pole B. Use a word that ends in er. (B is shorter. Shorter than A is even better.)","Point to the baskets. Say: Basket A has 3 apples and basket B has 8 apples. If you picked them both up, which one would be heavier? (B, because it has more apples in it.)","The answer has to use a comparing word: longer, shorter, heavier, or lighter. Pointing alone is not enough."]},{title:"Flat or Solid",std:["K.G.A.3"],n:3,dur:45,dir:"Look at the four cards. Answer out loud.",desc:"telling flat two dimensional shapes from solid three dimensional shapes",fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Four shape cards: 1 a yellow circle, 2 a purple square, 3 a blue cube, 4 a red can shape" src="data:image/webp;base64,${window.TP_IMG1.flat4}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["Say: Two of these shapes are flat, like a shape drawn on paper. Which two are flat? (1 and 2, the circle and the square)","Say: Two of them are solid. You could hold them in your hand. Which two are solid? (3 and 4, the cube and the can shape)","Say: Think about a real apple. Is an apple flat or solid? (solid)","Flat and two dimensional mean the same thing here, and so do solid and three dimensional. Either word counts."]}]},{id:19,title:"What Living Things Need",short:"Living Things",parts:[{std:["K-LS1-1"],n:3,dur:75,dir:"Look at each row. Answer out loud.",desc:"telling what plants and animals need to stay alive",html:()=>`<p class="big">An apple tree and a hen both live at the apple tree. Living things need certain things to stay alive.</p>
     <div class="figure">${ico("tree",96)}${ico("hen",96)}</div>`,qs:["The apple tree needs two of these to grow. Which two? Sunlight, water, or a ladder?","The hen needs two of these. Which two? Food, water, or a bell?","Name one thing the apple tree and the hen both need."],key:["sunlight and water. A ladder is for the picker, not for the tree.","food and water. A bell is not something a hen needs.","water. Both the tree and the hen need water. Accept air. Food counts only if the student explains that the tree makes its own."]}]},{id:20,title:"Weather at the Orchard",short:"Weather",parts:[{std:["K-ESS2-1"],n:3,dur:75,dir:"Look at the week of weather. Answer out loud.",desc:"describing a weather pattern from a week of observations",html:()=>`<p class="big">Here is one week of weather at the apple tree.</p>
     <table class="bigTable"><tr><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th></tr>
     <tr><td>${ico("sun",62)}</td><td>${ico("rain",62)}</td><td>${ico("cloud",62)}</td><td>${ico("rain",62)}</td><td>${ico("cloud",62)}</td></tr></table>`,qs:["How many cloudy days were there?","How many days had rain?","Was there more rain this week, or more sun?"],key:["2","2","more rain. There were 2 rainy days and only 1 sunny day. The student has to count both kinds to answer, so ask them to point as they count."]},{std:["K-ESS2-2"],n:2,dur:60,dir:"Answer out loud.",desc:"telling how a living thing changes its surroundings to get what it needs",html:()=>`<p class="big">A squirrel at the apple tree wants to save acorns to eat later.</p>
     <div class="figure">${ico("squirrel",88)}${ico("acorn",88)}</div>`,qs:["The squirrel digs a hole in the ground and buries the acorns in it. Did the squirrel change the ground, or did the ground change the squirrel?","Tell me one way a person changes the land to grow food."],key:["The squirrel changed the ground. It dug a hole that was not there before.","Any sensible answer about changing land on purpose: digging it up, pulling weeds, watering it, planting seeds, putting a fence around it."]}]},{id:21,title:"Homes, Forecasts and the Land",short:"Homes",parts:[{std:["K-ESS3-1"],n:3,dur:75,dir:"Match each animal to the place it lives. Answer out loud.",desc:"matching animals to the places that give them what they need",html:()=>`<p class="big">Animals live at the apple tree. Each one lives in one place. It gets what it needs.</p>
     <div class="figure">${ico("mouse",80)}${ico("bee",80)}${ico("owl",80)}</div>
     <p class="big">Here are the places. A hive. A hole in the ground. A hollow in an old tree.</p>`,qs:["Where does the mouse live?","Where does the bee live?","Where does the owl live?"],key:["a hole in the ground. Accept a burrow or a tunnel.","a hive","a hollow in an old tree. Accept a hole in a tree."]},{std:["K-ESS3-2"],dur:75,dir:"Answer out loud.",desc:"telling what a weather forecast is for",html:()=>`<p class="big">The farmer listens to the weather report the morning before picking day.</p>
     <div class="figure">${ico("radio",88)}${ico("wind",88)}</div>`,qs:["Why does she listen to the weather report? To find out if strong wind is coming, or to find out what day of the week it is?","What could the farmer do if strong wind was coming?","She wants to pick on a good day. What is one question she could ask about the weather?"],key:["to find out if strong wind is coming.","Any sensible answer: pick early, tie the ladder down, cover the crates, wait for a calm day.","Any real weather question: will it be windy, will it rain, how warm will it be."]},{std:["K-ESS3-3"],n:2,dur:60,dir:"Answer out loud.",desc:"telling one way people can take better care of the land and water",html:()=>`<p class="big">Two helpers fill watering cans at the apple tree tap.</p>
     <div class="figure">${ico("wateringCan",96)}${ico("drop",96)}</div>`,qs:["One helper turns the tap off as soon as her can is full. The other walks away and leaves the tap running. Which choice takes better care of the water?","Name one more thing people can do to take care of the water."],key:["turning the tap off as soon as the can is full","Any sensible answer: pick up litter, do not pour things down a drain, reuse a bag, plant something, put food scraps in a compost pile."]}]},{id:22,title:"Pushes and Pulls",short:"Push and Pull",parts:[{std:["K-PS2-1"],n:3,dur:75,dir:"Answer out loud. Let the student say the word push or pull first.",desc:"telling a push from a pull, and comparing a hard push with a gentle one",html:()=>`<p class="big">A push moves something away from you. A pull brings it toward you.</p>
     <div class="figure">${ico("box",88)}${ico("tractor",88)}</div>`,qs:["You hold the handle of a wagon of apples and bring it along behind you. Is that a push or a pull?","You slide a heavy crate of apples across the barn floor, away from you. Is that a push or a pull?","You tap an apple branch gently. Then you shake the same branch hard. Which one makes more apples fall?"],key:["a pull","a push","the hard shake. A stronger push or pull does more to the thing it acts on."]},{std:["K-PS2-2"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"deciding whether a change made a thing move faster or in a new direction",html:()=>`<p class="big">The helpers rolled the same apple along two different paths and counted the steps it rolled.</p>
     <table class="bigTable"><tr><th>Path</th><th>How far the apple rolled</th></tr>
     <tr><td>a smooth board</td><td>9 steps</td></tr><tr><td>the grass</td><td>2 steps</td></tr></table>`,qs:["Which path sent the apple farther?","An apple is rolling along the ground. You put your hand in its way and push back on it. What happens to the apple?"],key:["the smooth board, 9 steps","It slows down and stops, or it rolls back the other way. Either answer counts. The push changed how the apple was moving."]}]},{id:23,title:"Sun and Shade",short:"Sun",parts:[{std:["K-PS3-1"],n:2,dur:60,dir:"Answer out loud. If you can, feel a sunny spot and a shady spot together first.",desc:"telling what sunlight does to the things it shines on",html:()=>`<p class="big">Two buckets of water sit out at the apple tree all morning. One is in an open row. One is under an apple tree.</p>
     <div class="figure">${ico("sun",88)}${ico("tree",88)}</div>`,qs:["What warms the water in a bucket, the sun or the wind?","Which bucket is warmer by lunchtime, the one in the open row or the one under the tree?"],key:["the sun","the one in the open row"]},{std:["K-PS3-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"designing and drawing something that keeps a spot cooler",html:()=>`<p class="big">The apples are on a table. It is the farm stand table. They go soft in the sun. The afternoon sun is hot. Draw something over the table to make shade, like a cloth roof, a wide umbrella, or a tent top.</p>
     <div class="figure">${ico("tent",88)}${ico("umbrella",88)}</div>`,qs:["Draw your shade cover over the apple table.","Tell me how your cover keeps the apples cooler."],key:["Any cover drawn ABOVE the table. The three examples are in the direction, so copying one still counts. A screen drawn beside the table is partial: ask where the sun is coming from.","Something like: it blocks the sun, the sun cannot reach the apples, it puts the table in a shadow."]}]},{id:24,title:"Solving a Problem",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Listen, then answer out loud.",desc:"naming a problem people want to fix and asking about it",read:"Mira helps pick apples at the apple tree. She carries the picked apples to the crate in her two arms. On the way, two or three apples slip out, land on the hard ground, and bruise.",qs:["What is the problem? Apples slip out of her arms and bruise, or the apples are red?","Ask me a question about the apples that would help you fix it."],key:["Apples slip out of her arms and bruise on the ground.","Any real question: how many apples does she carry, how far away is the crate, how big are the apples, does she have a bag. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw your answer on your paper and hold it up.",desc:"drawing something whose shape would solve the problem",html:()=>`<p class="big">Draw something Mira could use to carry the apples without dropping them, like a basket, a bag with a strap, or a bucket with a handle.</p>
     <div class="figure">${ico("pack",88)}${ico("apple",88)}</div>`,qs:["Draw the thing you would use.","Tell me what you drew and how its shape holds the apples in."],key:["Any container that would hold apples: a basket, a bag, a bucket, a box, a deep pocket, an apron pouch. The three examples are in the direction, so copying one earns credit.","Naming it is what shows intent. Something like: the sides hold them in, the bag closes around them, the handle leaves her hands free."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Look at the chart. Answer out loud.",desc:"comparing test results from two fixes for the same problem",html:()=>`<p class="big">Mira tried two fixes and counted how many apples dropped each time.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Apples that dropped</th></tr>
     <tr><td>a basket with a handle</td><td>1</td></tr><tr><td>an open cloth bag</td><td>6</td></tr></table>`,qs:["Which fix lost fewer apples?","What on the chart shows that?"],key:["the basket with a handle","Because only 1 apple dropped with the basket and 6 dropped with the open bag. The reason has to come from the chart, not from liking baskets."]}]},{id:25,title:"Rules and Doing Right",short:"Rules",parts:[{std:["HSS-K.1"],n:3,dur:75,dir:"Listen, then answer out loud.",desc:"following rules, knowing what happens when they are broken, and naming an honest choice",read:"Jonah found a shiny coin on the orchard path and put it in his pocket. A little later he saw a girl walking along the same path, looking down at the ground. Jonah went over and asked her, did you lose a coin? She said yes. Jonah took the coin out of his pocket and handed it to her.",qs:["What did Jonah choose to do? Give the coin back, or keep it and say nothing?","One rule at the apple tree is stay on the path. What might happen if people walk wherever they like?","Tell me one rule you follow at a park or a library, and why it is there."],key:["He gave the coin back.","Young trees and new plants get stepped on, or someone gets lost between the rows. Any real consequence counts.","Any rule with a reason attached. The reason is the part to listen for."]}]},{id:26,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-K.4"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"telling land from water on a map, using position words, and naming places in a neighborhood",html:()=>`<p class="big">Here is a map of the orchard.</p>
     <div class="figure"><svg viewBox="0 0 300 180" width="300" height="180" role="img" aria-label="A map showing water around an island with a house and a tree"><rect x="2" y="2" width="296" height="176" rx="14" fill="#BFE3F5" stroke="#6B4A3C" stroke-width="3"/><g stroke="#5E8FA8" stroke-width="3" stroke-linecap="round" fill="none"><path d="M22 34 q10 -8 20 0 t20 0"/><path d="M232 34 q10 -8 20 0 t20 0"/><path d="M22 150 q10 -8 20 0 t20 0"/><path d="M232 150 q10 -8 20 0 t20 0"/><path d="M22 92 q10 -8 20 0 t20 0"/><path d="M232 92 q10 -8 20 0 t20 0"/></g><ellipse cx="150" cy="90" rx="92" ry="54" fill="#A8D49A" stroke="#6B4A3C" stroke-width="3"/><g transform="translate(110,92)"><rect x="-20" y="-6" width="40" height="32" rx="4" fill="#F2E3C6" stroke="#6B4A3C" stroke-width="3"/><path d="M-26 -6 L0 -28 L26 -6 Z" fill="#D9704F" stroke="#6B4A3C" stroke-width="3" stroke-linejoin="round"/><rect x="-7" y="8" width="14" height="18" rx="2" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.4"/></g><g transform="translate(192,92)"><rect x="-6" y="2" width="12" height="24" rx="3" fill="#A8724E" stroke="#6B4A3C" stroke-width="2.6"/><circle cx="0" cy="-8" r="22" fill="#6FB762" stroke="#6B4A3C" stroke-width="3"/></g></svg></div>
     <p class="big">${ico("cabin",64)} the farm stand &nbsp;&nbsp; ${ico("tree",64)} the apple rows &nbsp;&nbsp; ${ico("wave",64)} the pond</p>`,qs:["On a map, which color usually shows the water, and which color shows the land?","The pond is behind the apple rows. The farm stand is in front of them. Which one is behind the apple rows?","Is the pond near the farm stand or far from it?","Name two places you would find in your own town."],key:["Blue is water. Green or brown is land. Pointing to each one as they say it counts.","the pond","Either answer is fine as long as the student points and explains. The words near and far are what is being checked.","Any two real places: a store, a library, a park, a fire station, a school. A place from a story does not count."]}]},{id:27,title:"Our Flag and Long Ago",short:"Long Ago",parts:[{std:["HSS-K.2"],n:2,dur:60,dir:"Answer out loud.",desc:"recognizing the flag as a symbol of the country",html:()=>`<div class="figure">${ico("flag",120)}</div>`,qs:["What is this a picture of?","Our flag is a symbol. A symbol stands for something bigger than itself. What does our flag stand for?"],key:["a flag. Accept the flag of our country or the American flag.","our country, the United States, or all the people who live here. Any answer about the country counts."]},{std:["HSS-K.6"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what a holiday honors and how life long ago was different from life today",html:()=>`<p class="big">Farms had no tractors long ago. Americans still tell stories. They are about a man. He was called Johnny Appleseed. He walked for miles and miles. He had a bag of seeds. They were apple seeds. He planted apple trees. Families were moving west. They would find fruit waiting.</p>
     <div class="figure">${ico("horse",96)}${ico("tractor",96)}</div>`,qs:["Long ago, how did a farmer move a heavy load of apples, with a horse and wagon or with a tractor?","How does a farmer move a heavy load today?","Americans still tell the story of Johnny Appleseed. What did he do that people remember him for?"],key:["a horse and wagon","Any real answer: a tractor, a truck, a forklift, a cart with wheels. Naming today's way is the then-and-now half of this standard.","He planted apple trees, walking a long way with seeds so families moving west would find fruit growing. Accept planted apple trees. This is an American legend, which is the part of the standard about the stories our country tells. (HSS-K.6)"]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Count Higher",std:["1.NBT.A.1"],needs:["K.CC.A.1"],n:2,dir:"Count out loud. Then read the numbers.",html:()=>`<ol class="qlist"><li>Start at 87. Count out loud to 103.</li><li>Read each number.</li></ol>${wordGrid(["45","60","112"])}`,key:["87, 88, 89, 90 and on to 103 with no skips. Listen at 89 to 90 and at 99, 100, 101.","Reads forty-five, sixty, one hundred twelve"]},3:{id:"L3",lv:true,title:"Level Up: Sound Stretch",std:["RF.1.2"],needs:["RF.K.2"],n:3,dir:"Listen to your teacher. Answer out loud.",html:()=>`<div class="figure">${F.pic(EAR)}</div><ol class="qlist"><li>Put the sounds together to make a word.</li><li>Say every sound in the word.</li><li>Pick the word with the long vowel sound.</li></ol>`,key:["Say: /s/ /t/ /e/ /m/. What word? (stem)","Say: Tell me every sound in frog. (/f/ /r/ /o/ /g/, four sounds)","Ask: Which word has a long vowel sound, cap or cape? (cape)"]},7:{id:"L7",lv:true,title:"Level Up: Tricky Words",std:["RF.1.3"],needs:["RF.K.3"],n:3,dir:"Read each word out loud.",html:()=>wordGrid(["shed","chop","ripe"]),key:["Reads the first word (sh digraph, short e)","Reads the second word (ch digraph, short o)","Reads the third word (final e, long i)"]},8:{id:"L8",lv:true,title:"Level Up: Fruit Chart",std:["1.MD.C.4"],needs:["K.MD.B.3"],n:3,dir:"Look at the rows of fruit. Answer out loud.",html:()=>`<div style="text-align:center">${fruitRows([[AP,7],[PEAR,4],[LEMON,2]])}</div><ol class="qlist"><li>How many pieces of fruit are there in all?</li><li>How many more apples are there than pears?</li><li>How many fewer lemons are there than pears?</li></ol>`,key:["13 (7 apples, 4 pears, 2 lemons)","3 more apples (7 take away 4)","2 fewer lemons (4 take away 2)"]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=20;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}const STARTERS={apples:["This is an ____.","Apples are ____.","Apples grow ____."],trees:["This is a ____.","Trees have ____.","Trees can ____."],opinion:["I like ____.","I like it because ____."],story:["One day I ____.","Then I ____.","I felt ____."]};const SENTLAB={opinion:"If you are telling what you like:",story:"If you are telling a story:",apples:"If you are telling facts:",trees:"If you are telling facts:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const codes=[];parts.forEach(p=>(p.std||[]).forEach(c=>{if(codes.indexOf(c)<0)codes.push(c)}));const sets=[],add=k=>{if(STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)};codes.forEach(c=>{if(c==="W.K.1")add("opinion");else if(c==="W.K.3")add("story");else if(c==="W.K.2"||c==="W.K.8"){const p=parts.filter(q=>(q.std||[]).some(x=>x==="W.K.2"||x==="W.K.8"))[0];const t=p&&p.alt&&p.alt.key;add(STARTERS[t]?t:"apples")}});if(!sets.length){const p=parts[0],t=p&&p.alt&&p.alt.key;add(STARTERS[t]?t:"apples")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}function tpsCmpHtml(){const bar=(y,w,fill,lab)=>`<rect x="46" y="${y}" width="${w}" height="26" rx="7" fill="${fill}" stroke="var(--fig-ink)" stroke-width="2.5"/><text x="${54+w}" y="${y+14}" font-size="17" dominant-baseline="central" fill="var(--ink)">${lab}</text>`;const svg=`<svg viewBox="0 0 370 128" width="350" style="max-width:100%" role="img" aria-label="Two bars that both start at the same line. The top bar is longer and the bottom bar is shorter."><line x1="46" y1="14" x2="46" y2="110" stroke="var(--fig-ink)" stroke-width="3" stroke-dasharray="6 5"/>${bar(28,196,"var(--gold)","longer")}${bar(74,112,"var(--gold)","shorter")}<text x="46" y="124" font-size="14" text-anchor="middle" fill="var(--muted)">start</text></svg>`;return`<div class="figure">${svg}</div>`+F.table(["Word","What it means"],[["longer","it goes past the other one"],["shorter","it stops before the other one"],["taller","it goes higher than the other one"],["the same","they both end in the same place"]])+`<p class="small">Line both things up at the same start line. Then look at the other end to see which one goes further.</p>`}const tpsIco=(n,px)=>(F.icon||F.pic2)(n,px)||"";const TPS_ABC=[["a","apple","apple"],["b","bear","bear"],["c","cat","cat"],["d","dog","dog"],["e","egg","egg"],["f","fish","fish"],["g","goat","goat"],["h","hen","hen"],["i","island","island"],["j","jam",""],["k","key","key"],["l","leaf","leaf"],["m","moon","moon"],["n","nose","nose"],["o","octopus","octopus"],["p","pig","pig"],["q","queen",""],["r","rabbit","rabbit"],["s","sun","sun"],["t","tent","tent"],["u","umbrella","umbrella"],["v","van",""],["w","wave","wave"],["x","box, x at the end","box"],["y","yarn",""],["z","zip",""]];function tpsLetterHtml(){const cell=c=>`<div style="display:flex;flex-direction:column;align-items:center;gap:2px;min-width:70px;padding:6px 4px;border:2px solid var(--line);border-radius:10px"><b style="font-size:1.45rem;line-height:1">${c[0]} ${c[0].toUpperCase()}</b>${c[2]?tpsIco(c[2],30):""}<span style="font-size:.9rem;text-align:center">${c[1]}</span></div>`;return`<div class="tool-scroll"><div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center">${TPS_ABC.map(cell).join("")}</div></div><ul class="frames"><li>Point to a letter and ask for its sound, not its name.</li><li>Rhyme: two words that end with the same sounds, like cat and hat.</li><li>Word parts: clap once for each part you hear. Cam-per is two claps.</li><li>First sound: say only the sound at the start of the word.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who was there and where it was","First, ____."],["2. Next","what happened","Then, ____."],["3. Last","how it ended","Last, ____."]])+`<p class="small">Tell the three parts in that order. The card gives the order words, so the student supplies what happened.</p>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={np:{name:"Number line 0 to 20",std:["1.NBT.A.1","1.NBT.B.2","1.OA.A.1","K.CC.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:()=>window.TPNL20(),bind:(b,r)=>window.TPNL20Bind(b,r)},tf:{name:"Ten frames",std:["1.MD.C.4","1.NBT.B.2","1.OA.A.1","K.CC.B.4","K.CC.C.6","K.MD.B.3","K.NBT.A.1","K.OA.A.2","K.OA.A.3"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},sent:{name:"Sentence starters",std:["W.K.1","W.K.2","W.K.3","W.K.8"],html:sentHtml},cmp:{name:"Longer and shorter card",std:["K.MD.A.2"],html:tpsCmpHtml},letters:{name:"Letter and sound card",std:["RF.K.1","RF.K.2","RF.K.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["SL.K.4","W.K.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.K.1","RI.K.1","RL.K.1","SL.K.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.K.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"np",std:["K.CC.B.4"],msg:"The number line shows the counting order. Count On items done with it are supported, not independent."},{t:"sent",msg:"Sentence starters give the student the opening words, so count those checks as supported, not independent."},{t:"scribe",std:["W.K.2"],msg:"Telling an adult what to write is allowed for W.K.2."},{t:"scribe",std:["W.K.1","W.K.3","W.K.8"],msg:"Dictating to an adult is allowed for these writing standards. Note separately whether the student formed any letters without help."},{t:"tf",std:["K.OA.A.3","K.NBT.A.1"],msg:"If the ten frames were used to build the parts or the full ten, the student worked from a model you set up. Note it."},{t:"np",std:["K.OA.A.2"],msg:"The number line shows the counting order, so adding or subtracting along it is supported, not independent."},{t:"cmp",std:["K.MD.A.2"],msg:"The card supplies the words longer, shorter and taller, so rate on whether the student picks the right one, not on producing the word."},{t:"letters",std:["RF.K.1","RF.K.3"],msg:"The letter and sound card shows a keyword and a picture for each letter, so a sound read off the card is supported, not known by heart."},{t:"letters",std:["RF.K.2"],msg:"RF.K.2 is listening only. If the card was open, note that the student had the rhyme and the clapping rule in front of them."},{t:"retell",std:["SL.K.4","W.K.3"],msg:"The card gives the order words first, then and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.K.1","RI.K.1","L.K.1","SL.K.2","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.K.4"],msg:"A read with the reading window open is not a clean fluency check. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:[],onLeaveStop:()=>{DECKS.forEach(d=>d.reset())}}}});
